std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<> dis(-1.0, 1.0);

int insideCount = 0;
for (int i = 0; i < numberOfChecks; ++i) {
    // Generate random direction
    Vec3d dir(dis(gen), dis(gen), dis(gen));
    dir.normalize();

    // Create ray from point in random direction
    CGALRay ray(CGALPoint(p.x(), p.y(), p.z()), dir.x(), dir.y(), dir.z());

    // Count intersections
    int intersections = tree.numberIntersectedPrimitives(
        CGALPoint(p.x(), p.y(), p.z()),
        CGALPoint(p.x() + dir.x(), p.y() + dir.y(), p.z() + dir.z())
    );

    // If odd number of intersections, point is inside
    if (intersections % 2 == 1) {
        insideCount++;
    }
}

// If more than half of the rays show odd intersections, consider point inside
return insideCount > numberOfChecks / 2;

